UPDATE workspace_members
SET workspace_role = #{params.WorkspaceRole},
    updated_at = NOW()
WHERE organization_uuid = #{params.OrganizationUUID}
AND workspace_external_id = #{params.WorkspaceExternalID}
AND user_external_id = #{params.UserExternalID}
AND deleted_at IS NULL
RETURNING

UPDATE workspace_members
SET deleted_at = COALESCE(deleted_at, NOW()),
    updated_at = NOW()
WHERE organization_uuid = #{organizationUUID}
AND workspace_external_id = #{workspaceExternalID}
AND user_external_id = #{userExternalID}
AND deleted_at IS NULL
RETURNING
